// Agreement with PyTorch (float64) on reference runs generated by fixtures/generate.py.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  createRun,
  mlp,
  type Activation,
  type Dataset,
  type LossKind,
  type OptimizerKind,
} from '../src/index.ts';

interface Case {
  name: string;
  hidden: number[];
  acts: Activation[];
  opt: { kind: OptimizerKind; lr: number; weightDecay?: number };
  loss: LossKind;
  delta?: number;
  l1?: number;
  l2?: number;
  batch?: number;
  cosine?: [number, number];
  x: number[];
  y: number[];
  init: number[];
  losses: number[];
  final: number[];
}

const fixture = JSON.parse(
  readFileSync(new URL('./fixtures/torch.json', import.meta.url), 'utf8'),
) as {
  torch: string;
  epochs: number;
  cases: Case[];
};

/** |a - b| <= tol * (1 + |b|) for every entry; returns the worst ratio to that bound. */
function worst(a: ArrayLike<number>, b: ArrayLike<number>, tol: number): number {
  let w = 0;
  for (let i = 0; i < b.length; i++)
    w = Math.max(w, Math.abs(a[i] - b[i]) / (tol * (1 + Math.abs(b[i]))));
  return w;
}

describe(`matches PyTorch ${fixture.torch} (float64)`, () => {
  for (const c of fixture.cases) {
    it(c.name, () => {
      const config = mlp({
        hidden: c.hidden,
        activations: c.acts,
        optimizer: c.opt,
        loss: { kind: c.loss, ...(c.delta !== undefined ? { delta: c.delta } : {}) },
        l1: c.l1 ?? 0,
        l2: c.l2 ?? 0,
        batch: c.batch ? { kind: 'mini', size: c.batch, shuffle: false } : { kind: 'full' },
        schedule: c.cosine
          ? { kind: 'cosine', minLr: c.cosine[0], total: c.cosine[1] }
          : { kind: 'constant' },
      });
      const data: Dataset = {
        dim: 1,
        trainX: Float64Array.from(c.x),
        trainY: Float64Array.from(c.y),
        valX: new Float64Array(0),
        valY: new Float64Array(0),
        gridX: Float64Array.from([0]),
        clean: Float64Array.from([0]),
        region: Uint8Array.from([0]),
      };
      const run = createRun(config, data, 1);
      run.net.params.set(c.init);
      run.step(fixture.epochs);
      // Same algorithms in float64; measured agreement is a few ULPs (about 6e-16 relative).
      expect(worst(run.trainLoss, c.losses, 1e-13)).toBeLessThan(1);
      expect(worst(run.net.params, c.final, 1e-13)).toBeLessThan(1);
    });
  }
});
